function expRow(e){const m=mine(e),o=e.total!==m||e.payer!=='Yo',b=e.payer!=='Yo'?`pagó ${esc(e.payer)}`:(e.split||[]).length?`con ${e.split.map(esc).join(', ')}`:'';
  return `<button class="row" data-e="${e.id}"><span class="ico">${cat(e.cat)[2]}</span><span class="grow">${esc(e.title)}<br><span class="sm">${cat(e.cat)[1]}${b?' · '+b:''}</span></span><span class="num" style="text-align:right">${clp(e.total)}${o?`<br><span class="sm">tuyo ${clp(m)}</span>`:''}</span></button>`}
