function patch(a,b){
  if(a.id==='pics'&&a.dataset.k===b.dataset.k)return;
  for(const n of [...a.attributes])if(!b.hasAttribute(n.name))a.removeAttribute(n.name);
  for(const n of [...b.attributes])if(a.getAttribute(n.name)!==n.value){a.setAttribute(n.name,n.value);if(n.name==='value'&&document.activeElement!==a)a.value=n.value}
  if(a.tagName==='SELECT'&&a.value!==b.value)a.value=b.value;
  const x=[...a.childNodes],y=[...b.childNodes];
  y.forEach((c,i)=>{const o=x[i];if(!o)a.append(c);else if(o.nodeType===c.nodeType&&o.nodeName===c.nodeName){if(c.nodeType===1)patch(o,c);else if(o.nodeValue!==c.nodeValue)o.nodeValue=c.nodeValue}else o.replaceWith(c)});
  x.slice(y.length).forEach(o=>o.remove());
}
